static const int num_colors = sizeof(xkcd_colors) / sizeof(color_entry_t);

/**
 * @brief Initialize color database
 *
 * Colors are already in LAB format and pre-sorted by lightness in the source code.
 * Chroma and hue angles are pre-computed. This function is kept for API compatibility.
 */
void color_database_init(void)
{
    // No work needed - database is pre-initialized
}

/**
 * @brief Find the closest matching color using LAB color space
 *
 * Uses CIEDE2000 distance metric for perceptually accurate color matching.
 * This is a legacy function - consider using color_matcher for better performance.
 *
 * @param lab LAB color to match
 * @param out_delta_e Optional output for DeltaE2000 value (can be nullptr)
 * @return Pointer to the color name (static string)
 */
const char* find_closest_color_lab(const lab_t *lab, float *out_delta_e)
{
    float min_delta_e = FLT_MAX;
    int closest_index = 0;

    for (int i = 0; i < num_colors; i++)
    {
        float delta_e = color_math_delta_e_ciede2000(lab, &xkcd_colors[i].lab);
        if (delta_e < min_delta_e)
        {
            min_delta_e = delta_e;
            closest_index = i;
        }
    }

    if (out_delta_e != nullptr)
    {
        *out_delta_e = min_delta_e;
    }

    return xkcd_colors[closest_index].name;
}

/**
 * @brief Get the LAB values for a given color name
 *
 * Performs case-insensitive linear search through the color database.
 *
 * @param color_name Name of the color to lookup
 * @param out_lab Output LAB values (can be nullptr if not needed)
 * @return ESP_OK if found, ESP_ERR_INVALID_ARG if color_name is nullptr,
 *         ESP_ERR_NOT_FOUND if color name doesn't exist in database
 */
esp_err_t get_color_lab(const char *color_name, lab_t *out_lab)
{
    if (color_name == nullptr)
    {
        return ESP_ERR_INVALID_ARG;
    }

    // Linear search through the color database
    for (int i = 0; i < num_colors; i++)
    {
        if (strcasecmp(xkcd_colors[i].name, color_name) == 0)
        {
            if (out_lab != nullptr)
            {
                *out_lab = xkcd_colors[i].lab;
            }
            return ESP_OK;
        }
    }

    return ESP_ERR_NOT_FOUND;
}

/**
 * @brief Get total number of colors in database
 *
 * @return Number of color entries in the database
 */
uint32_t color_database_get_count(void)
{
    return num_colors;
}

/**
 * @brief Get color entry by index
 *
 * Retrieves color name and LAB values for a specific database index.
 * The database is pre-sorted by lightness (L* value).
 *
 * @param index Index in database (0 to count-1)
 * @param name Output buffer for name (can be nullptr if not needed)
 * @param name_size Size of name buffer
 * @param lab Output LAB color (can be nullptr if not needed)
 * @return ESP_OK on success, ESP_ERR_INVALID_ARG if index out of range
 */
esp_err_t color_database_get_entry(uint32_t index, char *name, size_t name_size, lab_t *lab)
{
    if (index >= num_colors)
    {
        return ESP_ERR_INVALID_ARG;
    }

    // Array is pre-sorted by lightness, so direct indexing works
    if (name && name_size > 0)
    {
        strncpy(name, xkcd_colors[index].name, name_size - 1);
        name[name_size - 1] = '\0';
    }

    if (lab)
    {
        *lab = xkcd_colors[index].lab;
    }

    return ESP_OK;
}

/**
 * @brief Get direct pointer to color name by index
 *
 * Returns a pointer to the static color name string without copying.
 * More efficient than color_database_get_entry when only the name is needed.
 *
 * @param index Index in database (0 to count-1)
 * @return Pointer to color name string, or NULL if index out of range
 */
const char* color_database_get_name(uint32_t index)
{
    if (index >= num_colors)
    {
        return NULL;
    }

    // Array is pre-sorted by lightness, so direct indexing works
    return xkcd_colors[index].name;
}
